///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_requestIdConf
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_requestIdConf = async function () {
    const sbmOptions = {
        id: "tx_fn_requestIdConf",
        method: "post",
        action: "/register/register.do?method=requestIdConf",
        ref: "dma_requestIdConfReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf55100.tx_fn_requestIdConf" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.requestIdConf
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.requestIdConf = async function () {
    /* sdd-asis-lifecycle:begin fn_requestIdConf — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.chkData()) {
        return false;
    }
    const SendForm = (document.SendForm || { elements: [] });
    $c.util.getComponent('dma_requestIdConfReq').set('encrypApctEmail', $c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue());
    scwin.form_SendForm.action = "/register/register.do?method=requestIdConf";
    scwin.form_SendForm.target = "_self";
    await scwin.tx_fn_requestIdConf();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkData = async function () {
    /* sdd-asis-lifecycle:begin fn_chkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const SendForm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "")) == 0) {
        await $c.win.alert("발행기관코드를 입력하십시오.");
        $c.util.getComponent("ipt_isurCd").setValue("");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    } else {
        if ($c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "").length < 5) {
            await $c.win.alert("발행기관코드 5자리를 입력하십시오.");
            $c.util.getComponent("ipt_isurCd").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_bzRegNo').getValue()) == 0) {
                await $c.win.alert("사업자등록번호를 입력하십시오.");
                $c.util.getComponent("ipt_bzRegNo").focus();
                return false;
            } else {
                if ($c.util.getComponent('ipt_bzRegNo').getValue().replace(/ /gi, "").length < 10) {
                    await $c.win.alert("사업자등록번호 10자리를 입력하십시오.");
                    $c.util.getComponent("ipt_bzRegNo").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) == 0) {
                        await $c.win.alert("이름을 입력하십시오.");
                        $c.util.getComponent("ipt_apctNm").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail1').getValue()) == 0) {
                            await $c.win.alert("이메일을 입력하십시오.");
                            $c.util.getComponent("ipt_encrypApctEmail1").focus();
                            return false;
                        } else {
                            if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail2').getValue()) == 0) {
                                await $c.win.alert("이메일을 입력하십시오.");
                                $c.util.getComponent("ipt_encrypApctEmail2").focus();
                                return false;
                            } else {
                                if (!$c.str.isEmail($c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue())) {
                                    await $c.win.alert("이메일이 올바르지 않습니다.");
                                    $c.util.getComponent("ipt_encrypApctEmail2").focus();
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
